import { useEffect, useMemo, useState } from 'react';
import { createClient } from '@supabase/supabase-js';
import { assignLiveReviewer, createLiveScholarship, getPrivateDocumentUrl, loadPortalData, removeLiveDocument, reviewLiveApplication, saveLiveDraft, sendLiveClarification, uploadLiveDocuments } from './portalApi.js';
import {
  ArrowLeft, ArrowRight, Bell, BookOpen, Check, CheckCircle2, ChevronDown,
  CircleHelp, Clock3, FileCheck2, FileText, Filter, GraduationCap, LayoutDashboard,
  LogOut, Menu, MoreHorizontal, Plus, Search, Settings2, ShieldCheck, Sparkles, Upload,
  Users, X, XCircle
} from 'lucide-react';

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
const supabase = supabaseUrl && supabaseKey ? createClient(supabaseUrl, supabaseKey) : null;
const initialApps = [
  { id:'app-1048', name:'Ananya Sharma', initials:'AS', email:'ananya.sharma@aarohan.edu.in', program:'B.Tech Computer Science', year:'2nd year', scholarship:'Aarohan Udaan Scholarship', submitted:'06 Oct 2026', status:'under_review', score:null, gpa:'8.4 / 10', need:'₹2.8 lakh / year', essay:'I grew up in Nashik and saw how access to digital services can make everyday tasks easier for families. I am studying computer science and volunteering with our campus coding club to help school students build confidence with technology. This scholarship would help me reduce my tuition burden and spend more time on my studies.' },
  { id:'app-1049', name:'Aarav Kulkarni', initials:'AK', email:'aarav.kulkarni@aarohan.edu.in', program:'B.Sc. Environmental Science', year:'3rd year', scholarship:'Aarohan Udaan Scholarship', submitted:'05 Oct 2026', status:'shortlisted', score:92, gpa:'8.8 / 10', need:'₹3.1 lakh / year', essay:'I want to work on practical ways to conserve water in Maharashtra. Through a college project, I helped map water use in nearby villages and learned that good research starts by listening to the people who will use it. The award would support my field visits and books.' },
  { id:'app-1050', name:'Zoya Khan', initials:'ZK', email:'zoya.khan@aarohan.edu.in', program:'B.Com. Finance', year:'1st year', scholarship:'Aarohan Udaan Scholarship', submitted:'04 Oct 2026', status:'needs_information', score:null, gpa:'81% in Class XII', need:'₹2.2 lakh / year', essay:'I am the first person in my family to attend university. I chose commerce because I hope to help small businesses in my community understand their finances and grow with confidence. I am eager to learn, contribute to campus life, and make the most of this opportunity.' },
  { id:'app-1051', name:'Rohan Das', initials:'RD', email:'rohan.das@aarohan.edu.in', program:'B.Tech Mechanical Engineering', year:'4th year', scholarship:'Aarohan Udaan Scholarship', submitted:'03 Oct 2026', status:'submitted', score:null, gpa:'8.1 / 10', need:'₹3.6 lakh / year', essay:'I enjoy turning classroom concepts into things that solve a real problem. My final-year team is prototyping a low-cost solar dryer for local farmers. Financial assistance would help me complete my degree and continue contributing to this work.' },
  { id:'app-1052', name:'Meera Nair', initials:'MN', email:'meera.nair@aarohan.edu.in', program:'B.A. Economics', year:'2nd year', scholarship:'Aarohan Udaan Scholarship', submitted:'02 Oct 2026', status:'approved', score:96, gpa:'9.1 / 10', need:'₹1.9 lakh / year', essay:'I want to understand how public policy affects families and how good evidence can lead to better decisions. I tutor school students on weekends and hope to work in education policy. This award would let me focus on my coursework and research.' },
];
const seedDraft = { fullName:'Priya Deshmukh', email:'priya.deshmukh@aarohan.edu.in', studentId:'AU-2026-0412', state:'Maharashtra', college:'Aarohan University, Pune', program:'B.Tech Computer Science', year:'2nd year', gpa:'8.2', household:'4', income:'280000', essay:'I want to study computer science because thoughtful technology can make useful services easier to reach. I have volunteered with our campus coding club and hope to build tools that solve practical problems in my community. This scholarship would ease the pressure of tuition and let me focus on my studies.' };
const docsSeed = [{ name:'Class XII marksheet.pdf', size:'1.2 MB', kind:'12th marksheet' }, { name:'Family income certificate.pdf', size:'840 KB', kind:'Income certificate' }];

const statusMeta = {
  draft:{ label:'Draft', tone:'muted' }, submitted:{ label:'Submitted', tone:'blue' }, under_review:{ label:'In review', tone:'violet' },
  needs_information:{ label:'Needs information', tone:'amber' }, shortlisted:{ label:'Shortlisted', tone:'green' }, declined:{ label:'Not selected', tone:'rose' },
  approved:{ label:'Approved', tone:'green' }, not_selected:{ label:'Not selected', tone:'rose' }
};

function readDemo() {
  try { return JSON.parse(localStorage.getItem('aarohan-demo-v2') || 'null'); } catch { return null; }
}
function Status({ value }) { const meta=statusMeta[value] || statusMeta.submitted; return <span className={`status status-${meta.tone}`}><i />{meta.label}</span>; }
function Avatar({ initials, size='' }) { return <span className={`avatar ${size}`}>{initials}</span>; }
function App() {
  const [role,setRole]=useState('student');
  const [page,setPage]=useState('overview');
  const [demo,setDemo]=useState(()=>readDemo() || { draft:seedDraft, docs:docsSeed, applications:initialApps, notice:'' });
  const [editing,setEditing]=useState(false);
  const [selected,setSelected]=useState('app-1048');
  const [query,setQuery]=useState('');
  const [filter,setFilter]=useState('all');
  const [toast,setToast]=useState('');
  const [mobileNav,setMobileNav]=useState(false);
  const [supabaseUser,setSupabaseUser]=useState(null);
  const [liveLoading,setLiveLoading]=useState(Boolean(supabase));
  const [liveError,setLiveError]=useState('');
  const [liveDraftId,setLiveDraftId]=useState(null);
  const [liveDraftStatus,setLiveDraftStatus]=useState('draft');
  const [liveScholarships,setLiveScholarships]=useState([]);
  const [selectedScholarshipId,setSelectedScholarshipId]=useState(null);
  const [liveReviewers,setLiveReviewers]=useState([]);
  const [liveAssignments,setLiveAssignments]=useState([]);
  const [signInOpen,setSignInOpen]=useState(false);
  const [email,setEmail]=useState('');
  const [busy,setBusy]=useState(false);
  useEffect(()=>{if(!supabase)localStorage.setItem('aarohan-demo-v2',JSON.stringify(demo));},[demo]);
  useEffect(()=>{ if(!supabase) return; supabase.auth.getSession().then(({data})=>{setSupabaseUser(data.session?.user||null);if(data.session?.user)setLiveLoading(true);}); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>{setSupabaseUser(s?.user||null);setLiveLoading(Boolean(s?.user));}); return ()=>subscription.unsubscribe(); },[]);
  useEffect(()=>{ if(!toast) return; const timer=setTimeout(()=>setToast(''),3000); return ()=>clearTimeout(timer); },[toast]);
  const currentApp=demo.applications.find(a=>a.id===selected) || demo.applications[0];
  const setApps=(fn)=>setDemo(d=>({...d,applications:typeof fn==='function'?fn(d.applications):fn}));
  const showToast=(s)=>setToast(s);
  const refreshLive=async(user=supabaseUser)=>{
    if(!supabase||!user)return;
    setLiveLoading(true);setLiveError('');
    try{const data=await loadPortalData(supabase,user);setRole(data.role);setLiveScholarships(data.scholarships);setSelectedScholarshipId(data.draftScholarshipId||data.scholarships.find(item=>item.is_active)?.id||null);setLiveReviewers(data.reviewers);setLiveAssignments(data.assignments);setLiveDraftId(data.draftId);setLiveDraftStatus(data.draftStatus);setDemo(d=>({...d,draft:data.draft,docs:data.documents,applications:data.applications}));if(data.applications[0]&&!data.applications.some(item=>item.id===selected))setSelected(data.applications[0].id);}
    catch(error){setLiveError(error.message||'Could not load portal data.');}
    finally{setLiveLoading(false);}
  };
  useEffect(()=>{if(supabaseUser)refreshLive(supabaseUser);else if(supabase){setLiveLoading(false);setRole('student');}},[supabaseUser]);
  const activeScholarshipId=selectedScholarshipId||liveScholarships.find(item=>item.is_active)?.id;
  const saveDraft=async()=>{try{if(supabase){const id=await saveLiveDraft(supabase,supabaseUser,activeScholarshipId,demo.draft,liveDraftId,liveDraftStatus);setLiveDraftId(id);await refreshLive();}setEditing(false);showToast(supabase?'Draft saved securely. You can come back to it any time.':'Draft saved in this browser.');}catch(error){showToast(error.message||'Could not save your draft.');}};
  const uploadFiles=async(files,documentType='supporting_document')=>{try{if(supabase){let id=liveDraftId;if(!id){id=await saveLiveDraft(supabase,supabaseUser,activeScholarshipId,demo.draft,null,'draft');setLiveDraftId(id);}const incoming=await uploadLiveDocuments(supabase,supabaseUser,id,files,documentType);setDemo(d=>({...d,docs:[...d.docs,...incoming]}));showToast(`${incoming.length} document${incoming.length===1?'':'s'} uploaded to private storage.`);return;}
    const kind=documentType==='class_xii_marksheet'?'12th marksheet':documentType==='family_income_certificate'?'Income certificate':'Supporting document';const incoming=Array.from(files).filter(f=>f.size<=10*1024*1024&&['application/pdf','image/jpeg','image/png'].includes(f.type)).map(f=>({name:f.name,size:f.size>1024*1024?`${(f.size/1024/1024).toFixed(1)} MB`:`${Math.max(1,Math.round(f.size/1024))} KB`,kind}));if(incoming.length){setDemo(d=>({...d,docs:[...d.docs,...incoming]}));showToast(`${incoming.length} sample document${incoming.length>1?'s':''} added. Files are not uploaded in demo mode.`);}else showToast('Use PDF, JPG, or PNG files up to 10 MB each.');}catch(error){showToast(error.message||'Upload failed.');}};
  const submitApplication=async()=>{
    const missing=[]; if(!demo.draft.fullName.trim())missing.push('full name'); if(!demo.draft.email.trim())missing.push('college email'); if(!demo.draft.program)missing.push('course'); if(!demo.draft.essay.trim()||demo.draft.essay.trim().length<80)missing.push('personal statement (at least 80 characters)'); if(!demo.docs.some(d=>d.kind==='12th marksheet'))missing.push('Class XII marksheet'); if(!demo.docs.some(d=>d.kind==='Income certificate'))missing.push('family income certificate');
    if(missing.length){showToast(`Please add: ${missing.join(', ')}.`);return;}
    if(supabase){try{let id=liveDraftId;if(!id){id=await saveLiveDraft(supabase,supabaseUser,activeScholarshipId,demo.draft,null,'draft');setLiveDraftId(id);}else await saveLiveDraft(supabase,supabaseUser,activeScholarshipId,demo.draft,id,liveDraftStatus);const {error}=await supabase.rpc('submit_application',{p_application_id:id});if(error)throw error;await refreshLive();setPage('tracking');showToast('Application submitted to the scholarship committee.');}catch(error){showToast(error.message||'Could not submit the application.');}return;}
    const a={id:`app-${Date.now()}`,name:demo.draft.fullName,initials:demo.draft.fullName.split(' ').map(x=>x[0]).join('').slice(0,2),email:demo.draft.email,program:demo.draft.program,year:demo.draft.year,scholarship:'Aarohan Udaan Scholarship',submitted:new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}),status:'submitted',score:null,gpa:demo.draft.gpa?`${demo.draft.gpa} / 10`:'—',need:'Needs-based',essay:demo.draft.essay};
    const awaitingClarification=demo.applications.find(x=>x.name===demo.draft.fullName&&x.status==='needs_information');
    if(awaitingClarification){setApps(list=>list.map(x=>x.id===awaitingClarification.id?{...x,...a,id:x.id,status:'under_review',clarificationResponse:'Updated application details and resubmitted.'}:x));}
    else setApps(list=>[a,...list]);
    setPage('tracking');showToast(awaitingClarification?'Clarification submitted. Your application is back in review.':'Application submitted. You can track its progress here.');
  };
  const decide=async(next,review={})=>{
    if(supabase){try{await reviewLiveApplication(supabase,currentApp.id,next,review);await refreshLive();showToast('Decision saved to the committee audit history.');}catch(error){showToast(error.message||'Could not save the review decision.');}return;}
    setApps(list=>list.map(a=>a.id===currentApp.id?{...a,status:next,score:review.score??a.score,reviewComment:review.comment||a.reviewComment||'',clarificationRequest:next==='needs_information'?(review.clarificationRequest||'Please provide the requested clarification.'):a.clarificationRequest}:a));
    showToast(next==='shortlisted'?'Sample application added to the shortlist.':next==='needs_information'?'Clarification request added to this sample application.':'Sample recommendation updated.');
  };
  const replyToClarification=async(applicationId,response)=>{if(supabase){try{const app=demo.applications.find(a=>a.id===applicationId);await sendLiveClarification(supabase,applicationId,app?.applicationData||demo.draft,response);await refreshLive();showToast('Clarification submitted. Your application is back with the committee.');}catch(error){showToast(error.message||'Could not send the clarification.');}return;}setApps(list=>list.map(a=>a.id===applicationId?{...a,status:'under_review',clarificationResponse:response}:a));showToast('Clarification sent. Your application is back in review.');};
  const startReview=async(id)=>{setSelected(id);setPage('reviewDetail');const a=demo.applications.find(x=>x.id===id);if(supabase&&a?.status==='submitted'){try{await reviewLiveApplication(supabase,id,'under_review',{});await refreshLive();}catch(error){showToast(error.message||'Could not open this application for review.');}}else if(!supabase&&a?.status==='submitted')setApps(list=>list.map(x=>x.id===id?{...x,status:'under_review'}:x));};
  const openPrivateDocument=async(doc)=>{if(!supabase||!doc.objectPath){showToast('This sample document is not stored as a file.');return;}const popup=window.open('about:blank','_blank');if(popup)popup.opener=null;try{const url=await getPrivateDocumentUrl(supabase,doc.objectPath);if(popup)popup.location.replace(url);else showToast('Allow pop-ups to open this private document.');}catch(error){popup?.close();showToast(error.message||'You are not authorized to view this document.');}};
  const removeDocument=async(doc)=>{try{if(supabase)await removeLiveDocument(supabase,doc);else setDemo(d=>({...d,docs:d.docs.filter(item=>item.name!==doc.name)}));if(supabase)await refreshLive();showToast('Document removed from this application.');}catch(error){showToast(error.message||'Could not remove this document.');}};
  const createScholarship=async(values)=>{try{if(supabase){const row=await createLiveScholarship(supabase,supabaseUser,values);setLiveScholarships(items=>[row,...items]);showToast('Scholarship created and saved.');}else{const row={id:`demo-${Date.now()}`,title:values.title,description:values.description,award_amount:Number(values.award_amount),deadline:new Date(values.deadline).toISOString(),eligibility:{family_income_below_inr:Number(values.income_limit),previous_exam_min_percent:Number(values.min_percent)},is_active:true};setDemo(d=>({...d,scholarships:[...(d.scholarships||[]),row]}));showToast('Sample scholarship added in this browser.');}}catch(error){showToast(error.message||'Could not create the scholarship.');}};
  const openScholarshipApplication=(id)=>{if(id)setSelectedScholarshipId(id);nav('application');};
  const assignReviewer=async(applicationId,reviewerId)=>{try{await assignLiveReviewer(supabase,supabaseUser,applicationId,reviewerId);setLiveAssignments(items=>items.some(row=>row.application_id===applicationId&&row.reviewer_id===reviewerId)?items:[...items,{application_id:applicationId,reviewer_id:reviewerId}]);showToast('Reviewer assigned to this application.');}catch(error){showToast(error.message||'Could not assign the reviewer.');}};
  const nav=(p)=>{setPage(p);setMobileNav(false);};
  const resetDemo=()=>{setDemo({draft:seedDraft,docs:docsSeed,applications:initialApps,notice:''});setRole('student');setPage('overview');showToast('Demo reset to the sample student and committee records.');};
  const sendMagicLink=async(e)=>{e.preventDefault();if(!supabase){showToast('Add Supabase settings to .env.local to enable sign-in.');return;}setBusy(true);const {error}=await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:window.location.origin}});setBusy(false);if(error)showToast(error.message);else{setSignInOpen(false);showToast('Sign-in link sent. Check your inbox.');}};
  const logout=async()=>{if(supabase)await supabase.auth.signOut();setSupabaseUser(null);showToast('Signed out.');};
  const reviewList=useMemo(()=>demo.applications.filter(a=>(filter==='all'||a.status===filter)&&`${a.name} ${a.program} ${a.scholarship}`.toLowerCase().includes(query.toLowerCase())),[demo.applications,filter,query]);

  if(supabase&&!supabaseUser)return <div className="auth-gate"><section className="card auth-gate-card"><span className="brand-mark"><GraduationCap size={20}/></span><div className="eyebrow">AAROHAN SCHOLARSHIP CELL</div><h1>Sign in to continue</h1><p>This portal is connected to its secure database. Sign in with your registered email; the committee role comes from your account permissions.</p><form onSubmit={sendMagicLink}><label htmlFor="gate-email">Email address</label><input id="gate-email" type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@college.edu.in"/><button className="btn btn-primary full" disabled={busy}>{busy?'Sending sign-in link…':'Email me a secure sign-in link'} <ArrowRight size={16}/></button></form>{toast&&<p className="auth-message" role="status">{toast}</p>}<small>Demo role switching is disabled when a live Supabase project is connected.</small></section></div>;
  if(supabase&&liveLoading)return <div className="auth-gate"><section className="card auth-gate-card"><span className="brand-mark"><GraduationCap size={20}/></span><h1>Loading your portal…</h1><p>Checking your account role and authorized scholarship records.</p></section></div>;
  if(supabase&&liveError)return <div className="auth-gate"><section className="card auth-gate-card"><span className="brand-mark"><ShieldCheck size={20}/></span><h1>Portal data could not load</h1><p>{liveError}</p><button className="btn btn-primary full" onClick={()=>refreshLive()}>Try again <ArrowRight size={16}/></button><button className="text-button signout" onClick={logout}><LogOut size={15}/> Sign out</button></section></div>;

  const sidebar=<aside className={`sidebar ${mobileNav?'open':''}`}>
    <a href="#top" className="brand" onClick={e=>e.preventDefault()}><span className="brand-mark"><GraduationCap size={20}/></span><span>aarohan<span className="brand-sub">SCHOLARSHIP CELL</span></span></a>
    <div className="workspace-label">WORKSPACE</div>
    <button className={`nav-item ${page==='overview'?'active':''}`} onClick={()=>nav('overview')}><LayoutDashboard size={18}/>Overview</button>
    {role==='student'&&<><button className={`nav-item ${page==='scholarships'?'active':''}`} onClick={()=>nav('scholarships')}><BookOpen size={18}/>Find scholarships</button><button className={`nav-item ${page==='application'?'active':''}`} onClick={()=>nav('application')}><FileText size={18}/>My application{demo.applications.some(a=>a.name===demo.draft.fullName)&&<span className="nav-count">1</span>}</button><button className={`nav-item ${page==='tracking'?'active':''}`} onClick={()=>nav('tracking')}><Clock3 size={18}/>Application status</button></>}
    {role==='reviewer'&&<><button className={`nav-item ${page==='reviewQueue'||page==='reviewDetail'?'active':''}`} onClick={()=>nav('reviewQueue')}><Users size={18}/>Review queue<span className="nav-count">{demo.applications.filter(a=>['submitted','under_review','needs_information'].includes(a.status)).length}</span></button><button className="nav-item" onClick={()=>nav('reviewQueue')}><CheckCircle2 size={18}/>Shortlist</button></>}
    {role==='admin'&&<><button className={`nav-item ${page==='adminScholarships'?'active':''}`} onClick={()=>nav('adminScholarships')}><BookOpen size={18}/>Scholarships</button><button className="nav-item" onClick={()=>nav('adminScholarships')}><Users size={18}/>Committee</button></>}
    <div className="sidebar-bottom"><div className="help-card"><span className="help-icon"><CircleHelp size={17}/></span><div><strong>Need help?</strong><small>Aarohan Scholarship Cell</small><button onClick={()=>showToast('Contact scholarships@aarohan.edu.in for help.')}>Get support <ArrowRight size={12}/></button></div></div><button className="profile-row" onClick={()=>setSignInOpen(true)}><Avatar initials={supabaseUser?.email?.slice(0,2).toUpperCase()||'PD'}/><span className="profile-text"><strong>{supabaseUser?.email||'Priya Deshmukh'}</strong><small>{role==='student'?'Student account':role==='reviewer'?'Review committee':'Portal admin'}</small></span><MoreHorizontal size={18}/></button></div>
  </aside>;

  return <div className="app-shell" id="top">{sidebar}{mobileNav&&<button className="nav-scrim" onClick={()=>setMobileNav(false)} aria-label="Close navigation"/>}<main className="main-area"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setMobileNav(true)} aria-label="Open menu"><Menu size={19}/></button><div className="crumb"><span>Aarohan University, Pune</span><span className="crumb-slash">/</span><strong>{pageTitle(page,role)}</strong></div><div className="top-actions"><span className="demo-pill"><i/>{supabase?`Live account · ${role}`:'Sample data · AY 2026–27'}</span><button className="icon-button" aria-label="Notifications" onClick={()=>showToast('You’re all caught up.')}><Bell size={18}/><i className="notification-dot"/></button><span className="top-divider"/>{supabase?<button className="live-role-button" onClick={()=>setSignInOpen(true)}>{supabaseUser?.email||'Signed-in account'} <ChevronDown size={14}/></button>:<div className="role-select-wrap"><label className="sr-only" htmlFor="role-select">Preview role</label><select id="role-select" value={role} onChange={e=>{setRole(e.target.value);setPage('overview')}}><option value="student">Student view</option><option value="reviewer">Reviewer view</option><option value="admin">Admin view</option></select><ChevronDown size={14}/></div>}</div></header>
  <div className="page-wrap">
    {role==='student'&&page==='overview'&&<StudentOverview name={demo.draft.fullName||supabaseUser?.email?.split('@')[0]||'Student'} featured={liveScholarships.find(item=>item.id===selectedScholarshipId)||liveScholarships.find(item=>item.is_active)} liveMode={Boolean(supabase)} draft={demo.draft} applications={demo.applications} docs={demo.docs} nav={nav} setEditing={setEditing} showToast={showToast}/>}
    {role==='student'&&page==='scholarships'&&<Scholarships nav={nav} records={liveScholarships} liveMode={Boolean(supabase)} onApply={openScholarshipApplication}/>}
    {role==='student'&&page==='application'&&<ApplicationPage draft={demo.draft} setDraft={v=>setDemo(d=>({...d,draft:typeof v==='function'?v(d.draft):v}))} docs={demo.docs} uploadFiles={uploadFiles} removeDocument={removeDocument} editing={editing} setEditing={setEditing} saveDraft={saveDraft} submitApplication={submitApplication} needsInfo={demo.applications.some(a=>a.name===demo.draft.fullName&&a.status==='needs_information')} liveMode={Boolean(supabase)} submitted={demo.applications.some(a=>a.name===demo.draft.fullName&&!['draft','needs_information'].includes(a.status))} showToast={showToast}/>}
    {role==='student'&&page==='tracking'&&<Tracking applications={demo.applications.filter(a=>a.name===demo.draft.fullName)} nav={nav} replyToClarification={replyToClarification}/>}
    {role==='reviewer'&&page==='overview'&&<ReviewerOverview applications={demo.applications} nav={nav}/>}
    {role==='reviewer'&&page==='reviewQueue'&&<ReviewQueue items={reviewList} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} startReview={startReview}/>}
    {role==='reviewer'&&page==='reviewDetail'&&currentApp&&<><ReviewDetail item={currentApp} onBack={()=>nav('reviewQueue')} decide={decide} showToast={showToast} liveMode={Boolean(supabase)} docs={currentApp.documents||docsSeed} openDocument={openPrivateDocument}/>{currentApp.status==='shortlisted'&&<section className="card final-decision"><div><div className="card-label">FINAL COMMITTEE DECISION</div><strong>Ready to decide on this shortlisted application?</strong></div><div><button className="btn btn-outline" onClick={()=>decide('not_selected')}><XCircle size={15}/> Not selected</button><button className="btn btn-primary" onClick={()=>decide('approved')}><Check size={15}/> Approve award</button></div></section>}</>}
    {role==='admin'&&page==='overview'&&<AdminOverview applications={demo.applications} nav={nav} scholarships={liveScholarships} liveMode={Boolean(supabase)}/>}
    {role==='admin'&&page==='adminScholarships'&&<AdminScholarships applications={demo.applications} showToast={showToast} scholarships={supabase?liveScholarships:(demo.scholarships||[])} reviewers={liveReviewers} assignments={liveAssignments} onCreate={createScholarship} onAssign={assignReviewer} liveMode={Boolean(supabase)}/>}
    <footer className="footer"><span>© 2026 Aarohan University · Pune, Maharashtra</span><span><a href="#privacy" onClick={e=>{e.preventDefault();showToast('Privacy details are part of the campus policy.')}}>Privacy</a><a href="#help" onClick={e=>{e.preventDefault();showToast('Contact scholarships@aarohan.edu.in for help.')}}>Help center</a>{!supabase&&<button onClick={resetDemo}>Reset sample data</button>}</span></footer>
  </div></main>
  {toast&&<div className="toast" role="status"><CheckCircle2 size={17}/><span>{toast}</span><button onClick={()=>setToast('')} aria-label="Dismiss"><X size={16}/></button></div>}
  {signInOpen&&<div className="modal-backdrop" onClick={()=>setSignInOpen(false)}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="signin-title" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setSignInOpen(false)} aria-label="Close"><X size={18}/></button><span className="brand-mark"><GraduationCap size={20}/></span><h2 id="signin-title">Sign in to Aarohan</h2><p>We’ll send a secure sign-in link to your college email.</p><form onSubmit={sendMagicLink}><label htmlFor="signin-email">College email</label><input id="signin-email" type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@aarohan.edu.in"/><button className="btn btn-primary full" disabled={busy}>{busy?'Sending…':'Send sign-in link'} <ArrowRight size={16}/></button></form>{!supabase&&<small className="demo-hint">Demo runs with sample data. Connect Supabase to enable sign-in.</small>}{supabaseUser&&<button className="text-button signout" onClick={logout}><LogOut size={15}/>Sign out</button>}</section></div>}
  </div>;
}

function pageTitle(p,r){if(p==='overview')return r==='student'?'Overview':r==='reviewer'?'Committee overview':'Admin overview';return ({scholarships:'Scholarships',application:'My application',tracking:'Application status',reviewQueue:'Review queue',reviewDetail:'Application review',adminScholarships:'Scholarship management'})[p]||'Overview';}
function SectionTitle({eyebrow,title,children}){return <div className="section-title"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1></div>{children}</div>}
function StudentOverview({name,featured,liveMode,draft,applications,docs,nav,setEditing,showToast}){
 const mine=applications.find(a=>a.name===draft.fullName);const progress=mine?100:Math.min(88,Math.round((Object.values(draft).filter(Boolean).length/9)*100));
 return <><div className="welcome-row"><div><div className="eyebrow">AAROHAN UNIVERSITY <span className="eyebrow-dot">·</span> ACADEMIC YEAR 2026–27</div><h1>Namaste, {name.split(' ')[0]} <span className="wave">✳</span></h1><p className="subheading">Your scholarship journey, all in one place.</p></div><button className="btn btn-primary" onClick={()=>{setEditing(true);nav('application')}}><Plus size={17}/> Continue application <ArrowRight size={16}/></button></div>
 <div className="student-grid"><div className="student-main"><section className="card featured-card"><div className="featured-top"><div className="card-label"><span className="tiny-icon purple"><Sparkles size={15}/></span> COLLEGE SCHOLARSHIP{liveMode?'':' · SAMPLE'}</div><span className="deadline-badge"><Clock3 size={13}/> Closes {featured?new Date(featured.deadline).toLocaleDateString('en-IN',{day:'2-digit',month:'short'}):'20 Oct'}</span></div><div className="feature-content"><div><h2>{featured?.title||<>Aarohan Udaan<br/>Scholarship</>}</h2><p>{featured?.description||'Fee support for students with strong academic goals.'}</p></div><div className="award"><strong>{featured?Number(featured.award_amount).toLocaleString('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}):'₹25,000'}</strong><span>per academic year</span></div></div><div className="featured-bottom"><span><Users size={15}/> Need-based <i>·</i> Undergraduate <i>·</i> Maharashtra</span><button className="text-button" onClick={()=>nav('scholarships')}>See eligibility <ArrowRight size={15}/></button></div><span className="feature-orb orb-one"/><span className="feature-orb orb-two"/></section>
 <section className="card application-card"><div className="card-header"><div><div className="card-label">YOUR APPLICATION CHECKLIST</div><h2>{mine?'Your application is moving forward':'A few steps to complete your application'}</h2></div><button className="text-button" onClick={()=>nav('application')}>{mine?'View application':'Open application'} <ArrowRight size={15}/></button></div><div className="progress-header"><span>{mine?'Submitted':'Application progress'}</span><strong>{mine?'100%':`${progress}%`}</strong></div><div className="progress-track"><span style={{width:`${mine?100:progress}%`}}/></div><div className="checklist">{[['Student and college details','Course, year and family information',true],['Personal statement','Your goals and why support matters',!!draft.essay],['Required documents','Class XII marksheet + income certificate',docs.some(d=>d.kind==='Income certificate')],['Review & submit','Check everything before sending',!!mine]].map((x,i)=><div className={`check-row ${x[2]?'done':''}`} key={x[0]}><span className="check-circle">{x[2]?<Check size={13}/>:<span>{i+1}</span>}</span><span className="check-copy"><strong>{x[0]}</strong><small>{x[1]}</small></span>{x[2]?<span className="check-state">Complete</span>:<button className="text-button" onClick={()=>nav('application')}>Continue <ArrowRight size={14}/></button>}</div>)}</div><button className="btn btn-outline continue-btn" onClick={()=>nav(mine?'tracking':'application')}>{mine?'Track your application':'Continue your application'} <ArrowRight size={15}/></button></section>
 <section className="card timeline-card"><div className="card-header"><div><div className="card-label">WHAT HAPPENS NEXT</div><h2>Here for every step</h2></div><button className="icon-button small" onClick={()=>showToast('Review timelines vary by scholarship.')} aria-label="About review timeline"><CircleHelp size={17}/></button></div><div className="mini-timeline"><div className="mini-step complete"><span><Check size={13}/></span><div><strong>Application started</strong><small>You’re on your way</small></div></div><div className={`mini-step ${mine?'complete':''}`}><span>{mine?<Check size={13}/>:<i/>}</span><div><strong>Committee review</strong><small>{mine?'Your application is with our committee':'After you submit your application'}</small></div></div><div className="mini-step"><span><i/></span><div><strong>Decision shared</strong><small>We’ll email you when it’s ready</small></div></div></div></section></div>
 <div className="student-side"><section className="side-welcome"><span className="side-illustration"><BookOpen size={24}/><Sparkles size={15}/></span><div className="card-label">A NOTE FOR YOU</div><h3>Small steps count.</h3><p>You don’t have to finish everything today. Your draft saves as you go.</p><button onClick={()=>nav('application')}>Pick up where you left off <ArrowRight size={14}/></button></section><section className="card side-card"><div className="card-header compact"><div className="card-label">YOUR DOCUMENTS</div><button className="text-button" onClick={()=>nav('application')}>Manage</button></div>{docs.slice(0,3).map(d=><div className="document-row" key={d.name}><span className="file-icon"><FileCheck2 size={16}/></span><span><strong>{d.name}</strong><small>{d.size} <i>·</i> Added</small></span><CheckCircle2 className="doc-ok" size={15}/></div>)}{docs.length===0&&<div className="empty-note">No documents yet. Add them in your application.</div>}</section><section className="quote-card"><span>“</span><p>Education is the most powerful weapon which you can use to change the world.</p><small>— Nelson Mandela</small><div className="quote-dots"><i/><i/><i/></div></section></div></div></>;
}
function Scholarships({nav,records=[],liveMode=false,onApply}){
 if(liveMode)return <><SectionTitle eyebrow="SCHOLARSHIP CELL · AY 2026–27" title="Find financial support"><button className="btn btn-outline" onClick={()=>nav('application')}>My application <ArrowRight size={15}/></button></SectionTitle><p className="subheading page-sub">Opportunities published by your scholarship cell. Review each deadline and eligibility before applying.</p><div className="scholarship-list">{records.map(record=>{const eligibility=record.eligibility||{};const isOpen=record.is_active&&new Date(record.deadline).getTime()>=Date.now();return <div className="card scholarship-tile" key={record.id}><div className="tile-icon saffron"><GraduationCap size={20}/></div><div className="tile-content"><div className="tile-meta"><span>COLLEGE SCHOLARSHIP · {isOpen?'OPEN':'CLOSED'}</span><span className="deadline-badge"><Clock3 size={13}/> {new Date(record.deadline).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}</span></div><h2>{record.title}</h2><p>{record.description||'See the scholarship cell for eligibility details.'}{eligibility.family_income_below_inr?` Eligibility: family income below ₹${Number(eligibility.family_income_below_inr).toLocaleString('en-IN')} per year.`:''}{eligibility.previous_exam_min_percent?` At least ${eligibility.previous_exam_min_percent}% in the previous exam.`:''}</p><div className="tile-footer"><strong>{Number(record.award_amount).toLocaleString('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0})}<small>per academic year</small></strong><button className="btn btn-primary" disabled={!isOpen} onClick={()=>onApply(record.id)}>{isOpen?'Apply through college':'Applications closed'} <ArrowRight size={15}/></button></div></div></div>})}{!records.length&&<div className="card empty-card"><h2>No open college scholarships</h2><p>Check back after your scholarship cell publishes an opportunity.</p></div>}<OfficialSchemeTile/></div></>;
 return <><SectionTitle eyebrow="SCHOLARSHIP CELL · AY 2026–27" title="Find financial support"><button className="btn btn-outline" onClick={()=>nav('application')}>My application <ArrowRight size={15}/></button></SectionTitle><p className="subheading page-sub">College support and verified public schemes. Check the official notice before applying; eligibility and deadlines can change.</p><div className="scholarship-list"><div className="card scholarship-tile"><div className="tile-icon saffron"><GraduationCap size={20}/></div><div className="tile-content"><div className="tile-meta"><span>COLLEGE SCHEME · SAMPLE RECORD · MAHARASHTRA</span><span className="deadline-badge"><Clock3 size={13}/> 20 Oct 2026</span></div><h2>Aarohan Udaan Scholarship</h2><p>Annual fee support for full-time undergraduate students at Aarohan University. Demo eligibility: family income below ₹5 lakh per year, at least 70% in the previous examination, and current enrolment in an undergraduate course. Submit a Class XII/previous-year marksheet and family income certificate.</p><div className="tile-footer"><strong>₹25,000 <small>per academic year · sample award</small></strong><button className="btn btn-primary" onClick={()=>nav('application')}>Apply through college <ArrowRight size={15}/></button></div></div></div><OfficialSchemeTile/><div className="info-strip"><ShieldCheck size={17}/><span><strong>Protect your information.</strong> This college demo uses sample applications. For government schemes, apply only through the linked official portal and never share OTPs or banking passwords.</span></div></div></>;
}
function OfficialSchemeTile(){return <div className="card scholarship-tile"><div className="tile-icon green"><BookOpen size={20}/></div><div className="tile-content"><div className="tile-meta"><span>GOVERNMENT OF INDIA · PM-USP CSSS</span><span className="deadline-badge"><Clock3 size={13}/> 31 Oct 2026</span></div><h2>Central Sector Scheme of Scholarship for College and University Students</h2><p>For eligible students in the top 20th percentile of their Class XII board results, with family income up to ₹4.5 lakh per year. The Ministry of Education lists ₹12,000 per year for the first three undergraduate years; technical courses receive ₹20,000 in year four. Apply through the National Scholarship Portal.</p><div className="tile-footer"><strong>₹12,000–₹20,000 <small>per year · varies by course/year</small></strong><a className="btn btn-outline" href="https://scholarships.gov.in/All-Scholarships" target="_blank" rel="noreferrer">Open official NSP listing <ArrowRight size={15}/></a></div><div className="source-note">Official details: <a href="https://www.education.gov.in/sites/upload_files/mhrd/files/upload_document/PM_USP_CSSS_guidelines.pdf" target="_blank" rel="noreferrer">Ministry of Education guidelines</a></div></div></div>}
function ApplicationPage({draft,setDraft,docs,uploadFiles,removeDocument,editing,setEditing,saveDraft,submitApplication,submitted,needsInfo,liveMode,showToast}){
 const [tab,setTab]=useState('details');const [documentType,setDocumentType]=useState('class_xii_marksheet');const field=(key,value)=>setDraft(d=>({...d,[key]:value}));const locked=submitted;
 return <><SectionTitle eyebrow="AAROHAN UDAAN SCHOLARSHIP · SAMPLE" title="Your application"><div className="header-actions"><Status value={needsInfo?'needs_information':submitted?'submitted':'draft'}/><button className="btn btn-outline" disabled={submitted} onClick={saveDraft}>{submitted?'Submitted':'Save draft'}</button></div></SectionTitle>{!liveMode&&<div className="demo-data-warning" role="status"><ShieldCheck size={16}/><span><strong>Sample mode:</strong> form text and file names are saved only in this browser. Use fictional information for your demo.</span></div>}{needsInfo&&<div className="clarification-reply"><strong>Committee clarification requested</strong><p>Check Application status to read the committee’s question and send your reply.</p><small>You may also update these details and resubmit.</small></div>}<div className="application-layout"><div className="application-form-wrap"><div className="form-progress"><div className="form-progress-label"><span>Application steps</span><strong>Step {tab==='details'?1:tab==='statement'?2:3} of 3</strong></div><div className="step-track"><span className={tab!=='details'?'active':''}/><span className={tab==='review'?'active':''}/><span/></div><div className="form-tabs"><button className={tab==='details'?'active':''} onClick={()=>setTab('details')}>01 <span>About you</span></button><button className={tab==='statement'?'active':''} onClick={()=>setTab('statement')}>02 <span>Your story</span></button><button className={tab==='review'?'active':''} onClick={()=>setTab('review')}>03 <span>Review</span></button></div></div>
 {tab==='details'&&<section className="card form-card"><div className="form-heading"><span className="form-step-icon"><Users size={18}/></span><div><h2>Student and college details</h2><p>Use the details from your college records.</p></div></div><div className="form-grid"><Field label="Full name" required><input disabled={locked} value={draft.fullName} onChange={e=>field('fullName',e.target.value)} placeholder="As shown on your marksheet"/></Field><Field label="College email" required><input disabled={locked} type="email" value={draft.email} onChange={e=>field('email',e.target.value)} placeholder="you@college.edu.in"/></Field><Field label="Student / enrolment ID"><input disabled={locked} value={draft.studentId} onChange={e=>field('studentId',e.target.value)} placeholder="Your college ID"/></Field><Field label="College / university"><input disabled={locked} value={draft.college} onChange={e=>field('college',e.target.value)} placeholder="College name and city"/></Field><Field label="State / UT"><select disabled={locked} value={draft.state} onChange={e=>field('state',e.target.value)}>{['Andhra Pradesh','Assam','Bihar','Delhi','Gujarat','Karnataka','Kerala','Madhya Pradesh','Maharashtra','Rajasthan','Tamil Nadu','Telangana','Uttar Pradesh','West Bengal','Other'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Course of study" required><select disabled={locked} value={draft.program} onChange={e=>field('program',e.target.value)}><option value="">Choose a course</option>{['B.Tech Computer Science','B.Tech Mechanical Engineering','B.Sc. Environmental Science','B.Sc. Mathematics','B.Com. Finance','B.A. Economics','BBA','Other'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Current year"><select disabled={locked} value={draft.year} onChange={e=>field('year',e.target.value)}>{['1st year','2nd year','3rd year','4th year','5th year','Postgraduate'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Current CGPA / percentage" hint="Use your college's grading scale"><input disabled={locked} value={draft.gpa} onChange={e=>field('gpa',e.target.value)} placeholder="e.g. 8.2 / 10 or 82%"/></Field><Field label="People in your household" hint="Include yourself"><input disabled={locked} type="number" min="1" value={draft.household} onChange={e=>field('household',e.target.value)} placeholder="e.g. 4"/></Field><Field label="Annual family income (₹)" hint="Enter approximate amount in rupees"><div className="input-prefix"><span>₹</span><input disabled={locked} type="number" value={draft.income} onChange={e=>field('income',e.target.value)} placeholder="e.g. 280000"/></div></Field></div><div className="form-footer"><span><ShieldCheck size={14}/> Do not enter Aadhaar or bank details here.</span><button className="btn btn-primary" onClick={()=>setTab('statement')}>Continue <ArrowRight size={15}/></button></div></section>}
 {tab==='statement'&&<section className="card form-card"><div className="form-heading"><span className="form-step-icon"><FileText size={18}/></span><div><h2>Your story, in your words</h2><p>There’s no perfect answer. Tell us what matters to you.</p></div></div><Field label="Personal statement" required hint="What are you working toward, and how would this scholarship help? (At least 80 characters)"><textarea disabled={locked} rows="8" maxLength="1200" value={draft.essay} onChange={e=>field('essay',e.target.value)} placeholder="Start wherever feels right…"/></Field><div className="character-count">{draft.essay.length} / 1,200 characters</div><div className="upload-section"><div><strong>Supporting documents <span className="required">*</span></strong><small>Upload your Class XII / previous-year marksheet and family income certificate. PDF, JPG, PNG · Max 10 MB.</small></div><div className="upload-controls"><label className="document-type-select">Document type<select value={documentType} onChange={e=>setDocumentType(e.target.value)} disabled={locked}><option value="class_xii_marksheet">Class XII / previous-year marksheet</option><option value="family_income_certificate">Family income certificate</option><option value="supporting_document">Other supporting document</option></select></label><label className={`upload-drop ${locked?'disabled':''}`}><Upload size={18}/><span><strong>Choose files</strong> or drop them here</span><input type="file" multiple accept="application/pdf,image/jpeg,image/png" disabled={locked} onChange={e=>{uploadFiles(e.target.files,documentType);e.target.value='';}}/></label></div><small className="comment-help">{liveMode?'Files upload to private storage and are available only to authorized users.':'Demo mode: file names are simulated; file contents are not uploaded.'}</small><div className="uploaded-list">{docs.map(d=><div className="uploaded-file" key={d.name}><span className="file-icon"><FileCheck2 size={16}/></span><span><strong>{d.name}</strong><small>{d.size} · {d.kind}</small></span><button className="icon-button small" disabled={locked} onClick={()=>removeDocument(d)} aria-label={`Remove ${d.name}`}><X size={16}/></button></div>)}</div></div><div className="form-footer"><button className="text-button" onClick={()=>setTab('details')}><ArrowLeft size={15}/> Back</button><button className="btn btn-primary" onClick={()=>setTab('review')}>Review application <ArrowRight size={15}/></button></div></section>}
 {tab==='review'&&<section className="card form-card"><div className="form-heading"><span className="form-step-icon"><CheckCircle2 size={18}/></span><div><h2>Ready when you are</h2><p>Take a moment to look everything over.</p></div></div><div className="review-summary"><div className="summary-heading"><strong>About you</strong><button className="text-button" onClick={()=>setTab('details')}>Edit <ArrowRight size={13}/></button></div><div className="summary-grid"><span><small>Full name</small><strong>{draft.fullName||'Not added yet'}</strong></span><span><small>Campus email</small><strong>{draft.email||'Not added yet'}</strong></span><span><small>Program</small><strong>{draft.program||'Not selected yet'}</strong></span><span><small>Year of study</small><strong>{draft.year}</strong></span></div><div className="summary-heading"><strong>Your personal statement</strong><button className="text-button" onClick={()=>setTab('statement')}>Edit <ArrowRight size={13}/></button></div><p className="summary-essay">{draft.essay||'No statement added yet.'}</p><div className="summary-heading"><strong>Supporting documents ({docs.length})</strong><button className="text-button" onClick={()=>setTab('statement')}>Manage <ArrowRight size={13}/></button></div>{docs.map(d=><div className="summary-doc" key={d.name}><FileCheck2 size={15}/>{d.name}<span>{d.size}</span></div>)}</div><div className="privacy-note"><ShieldCheck size={17}/><span><strong>Your application is private.</strong><br/>Only authorized scholarship reviewers can access your information.</span></div><div className="form-footer"><button className="text-button" onClick={()=>setTab('statement')}><ArrowLeft size={15}/> Back</button>{submitted?<span className="submitted-note"><CheckCircle2 size={16}/> Application submitted</span>:<button className="btn btn-primary" onClick={submitApplication}>Submit application <ArrowRight size={15}/></button>}</div></section>}
 </div><aside className="application-aside"><section className="card aside-info"><div className="card-label">APPLICATION DETAILS</div><div className="aside-detail"><span>Scholarship</span><strong>Aarohan Udaan Scholarship · Sample</strong></div><div className="aside-detail"><span>Award amount</span><strong>₹25,000 / year</strong></div><div className="aside-detail"><span>Deadline</span><strong className="deadline-text">20 October 2026</strong></div><div className="aside-detail"><span>Required documents</span><strong>Class XII marksheet + income certificate</strong></div><div className="aside-detail"><span>Demo eligibility</span><strong>Undergraduate · family income below ₹5 lakh</strong></div></section><section className="aside-tip"><Sparkles size={16}/><div><strong>Keep it simple</strong><p>Share your goals in your own words. A clear, honest statement is enough.</p></div></section><div className="secure-caption"><ShieldCheck size={14}/> Aarohan Scholarship Cell · Pune, Maharashtra</div></aside></div></>;
}
function Field({label,required,hint,children}){return <label className="field"><span>{label}{required&&<b className="required"> *</b>}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Tracking({applications,nav,replyToClarification}){
 const app=applications[0];const [response,setResponse]=useState('');
 if(!app)return <><SectionTitle eyebrow="YOUR PROGRESS" title="Application status"/><section className="card empty-card"><span className="empty-icon"><FileText size={23}/></span><h2>Your story starts here.</h2><p>Once you submit an application, you can follow every step from this page.</p><button className="btn btn-primary" onClick={()=>nav('application')}>Start an application <ArrowRight size={15}/></button></section></>;
 
 return <><SectionTitle eyebrow="YOUR PROGRESS" title="Application status"><Status value={app.status}/></SectionTitle><p className="subheading page-sub">We’ll keep you updated at every step.</p><section className="card tracking-card"><div className="tracking-top"><span className="tracking-award"><GraduationCap size={18}/></span><div><small>SCHOLARSHIP APPLICATION</small><h2>{app.scholarship}</h2><span>Submitted {app.submitted}</span></div><Status value={app.status}/></div>
 {app.status==='needs_information'&&<div className="clarification-box"><div className="card-label">ACTION NEEDED FROM YOU</div><h3>The committee needs one more detail</h3><p>{app.clarificationRequest||'Please provide the requested clarification so the committee can continue reviewing your application.'}</p><label htmlFor="clarification-response">Your reply</label><textarea id="clarification-response" rows="4" value={response} onChange={e=>setResponse(e.target.value)} placeholder="Write a short response for the review committee…"/><button className="btn btn-primary" disabled={!response.trim()} onClick={()=>replyToClarification(app.id,response.trim())}>Send clarification <ArrowRight size={15}/></button><small>This prototype stores your reply only in this browser.</small></div>}
 {app.clarificationResponse&&<div className="clarification-reply"><strong>Your clarification sent</strong><p>{app.clarificationResponse}</p></div>}
 <div className="tracking-timeline">{[['submitted','Application submitted','Your application is with us.'],['under_review','Committee review',app.status==='needs_information'?'The committee paused its review and requested a clarification.':'The committee is reviewing your materials.'],[app.status==='shortlisted'||app.status==='approved'?'shortlisted':'decision','Committee decision',app.status==='shortlisted'?'You’ve been shortlisted. The final decision is coming soon.':app.status==='approved'?'Your scholarship has been approved.':app.status==='not_selected'||app.status==='declined'?'The committee has completed its decision.':'We’ll let you know as soon as a decision is ready.']].map((step,i)=>{const done=(i===0)||((i===1)&&['under_review','needs_information','shortlisted','approved','declined','not_selected'].includes(app.status))||((i===2)&&['shortlisted','approved','declined','not_selected'].includes(app.status));return <div className={`tracking-step ${done?'done':''} ${i===2?'last':''}`} key={step[0]}><span className="tracking-node">{done?<Check size={14}/>:<i/>}</span><div><strong>{step[1]}</strong><p>{step[2]}</p></div><small>{done?i===0?app.submitted:'Updated':'Up next'}</small></div>})}</div><div className="tracking-contact"><span className="help-icon"><CircleHelp size={17}/></span><span><strong>Questions about your application?</strong><small>Our student support team can help.</small></span><a href="mailto:scholarships@aarohan.edu.in">Contact support <ArrowRight size={14}/></a></div></section><button className="text-button back-link" onClick={()=>nav('overview')}> <ArrowLeft size={15}/> Back to overview</button></>;
}
function ReviewerOverview({applications,nav}){const pending=applications.filter(a=>['submitted','under_review'].includes(a.status)).length,short=applications.filter(a=>a.status==='shortlisted').length,need=applications.filter(a=>a.status==='needs_information').length;return <><div className="welcome-row"><div><div className="eyebrow">COMMITTEE WORKSPACE</div><h1>Good morning, Dr. Rivera</h1><p className="subheading">A thoughtful review can change someone’s path.</p></div><button className="btn btn-primary" onClick={()=>nav('reviewQueue')}>Open review queue <ArrowRight size={16}/></button></div><div className="stats-grid"><Stat label="To review" value={pending} meta="Awaiting your review" icon={<FileText size={17}/>} tone="violet"/><Stat label="Shortlisted" value={short} meta="Across this scholarship" icon={<CheckCircle2 size={17}/>} tone="green"/><Stat label="Need information" value={need} meta="Waiting on students" icon={<Clock3 size={17}/>} tone="amber"/></div><div className="reviewer-lower"><section className="card overview-queue"><div className="card-header"><div><div className="card-label">YOUR NEXT REVIEWS</div><h2>Applications to look at</h2></div><button className="text-button" onClick={()=>nav('reviewQueue')}>View all <ArrowRight size={15}/></button></div>{applications.filter(a=>['submitted','under_review'].includes(a.status)).slice(0,3).map((a,i)=><button className="quick-review-row" key={a.id} onClick={()=>nav('reviewQueue')}><Avatar initials={a.initials}/><span><strong>{a.name}</strong><small>{a.program} <i>·</i> {a.scholarship}</small></span><span className="queue-time">{a.submitted}</span><ArrowRight size={16}/></button>)}<button className="btn btn-outline full" onClick={()=>nav('reviewQueue')}>Go to review queue <ArrowRight size={15}/></button></section><section className="review-principle"><ShieldCheck size={19}/><div className="card-label">A FAIR REVIEW</div><h3>Every story deserves a thoughtful read.</h3><p>Use the shared rubric to guide your review. Use the shared rubric to keep committee decisions consistent. In this demo, changes stay in this browser.</p><button onClick={()=>showGuidance(nav)}>View review guidelines <ArrowRight size={14}/></button></section></div></>}
function showGuidance(nav){nav('reviewQueue')}
function Stat({label,value,meta,icon,tone}){return <section className="card stat-card"><span className={`stat-icon ${tone}`}>{icon}</span><div><span>{label}</span><strong>{value}</strong><small>{meta}</small></div><span className="stat-trend">↗</span></section>}
function ReviewQueue({items,query,setQuery,filter,setFilter,startReview}){return <><SectionTitle eyebrow="COMMITTEE WORKSPACE" title="Review queue"><span className="queue-total"><strong>{items.length}</strong> applications</span></SectionTitle><p className="subheading page-sub">Review each application with care using the shared committee rubric.</p><section className="card queue-card"><div className="queue-toolbar"><label className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search students or programs" aria-label="Search applications"/>{query&&<button onClick={()=>setQuery('')} aria-label="Clear search"><X size={14}/></button>}</label><label className="filter-select"><Filter size={15}/><select value={filter} onChange={e=>setFilter(e.target.value)} aria-label="Filter applications"><option value="all">All applications</option><option value="submitted">Submitted</option><option value="under_review">In review</option><option value="needs_information">Needs information</option><option value="shortlisted">Shortlisted</option></select><ChevronDown size={14}/></label><button className="icon-button" onClick={()=>{setQuery('');setFilter('all')}} aria-label="Reset filters"><Settings2 size={17}/></button></div><div className="queue-table-wrap"><table className="queue-table"><thead><tr><th>STUDENT</th><th>PROGRAM</th><th>SCHOLARSHIP</th><th>SUBMITTED</th><th>STATUS</th><th></th></tr></thead><tbody>{items.map(a=><tr key={a.id} onClick={()=>startReview(a.id)} tabIndex="0" onKeyDown={e=>e.key==='Enter'&&startReview(a.id)}><td><span className="student-cell"><Avatar initials={a.initials}/><span><strong>{a.name}</strong><small>{a.email}</small></span></span></td><td>{a.program}<small className="table-secondary">{a.year}</small></td><td>{a.scholarship}</td><td>{a.submitted}</td><td><Status value={a.status}/></td><td><button className="icon-button small" aria-label={`Review ${a.name}`}><ArrowRight size={16}/></button></td></tr>)}</tbody></table>{items.length===0&&<div className="empty-note centered">No applications match your search.</div>}</div><div className="table-footer"><span>Showing <strong>{items.length}</strong> of <strong>{items.length}</strong> applications</span><span>Last updated just now</span></div></section><div className="review-privacy"><ShieldCheck size={15}/> Student information is confidential. Access only applications assigned to your committee.</div></>}
function ReviewDetail({item,onBack,decide,docs,openDocument,showToast,liveMode}){const [rubric,setRubric]=useState({purpose:4,impact:4,readiness:4});const [comment,setComment]=useState('');const [clarificationRequest,setClarificationRequest]=useState('');const average=Object.values(rubric).reduce((a,b)=>a+b,0);const reviewPayload={score:Math.round(average/15*100),comment,clarificationRequest,rubric};return <><button className="text-button back-link" onClick={onBack}><ArrowLeft size={15}/> Back to queue</button><div className="review-detail-head"><div><div className="eyebrow">APPLICATION REVIEW <span className="eyebrow-dot">·</span> {item.id.toUpperCase()}</div><h1>{item.name}</h1><p className="subheading">{item.program} <i>·</i> {item.year} <i>·</i> Submitted {item.submitted}</p></div><Status value={item.status}/></div><div className="detail-grid"><div className="review-content"><section className="card detail-card"><div className="card-header"><div><div className="card-label">STUDENT PROFILE</div><h2>Getting to know {item.name.split(' ')[0]}</h2></div><Avatar initials={item.initials} size="large"/></div><div className="profile-facts"><span><small>Program</small><strong>{item.program}</strong></span><span><small>Year</small><strong>{item.year}</strong></span><span><small>Current GPA</small><strong>{item.gpa}</strong></span><span><small>Financial need</small><strong>{item.need}</strong></span><span><small>Email</small><strong>{item.email}</strong></span></div></section><section className="card detail-card"><div className="card-header"><div><div className="card-label">PERSONAL STATEMENT</div><h2>In their own words</h2></div><span className="read-time">~1 min read</span></div><p className="essay-text">{item.essay}</p></section><section className="card detail-card"><div className="card-header"><div><div className="card-label">SUPPORTING DOCUMENTS</div><h2>Application materials</h2></div><span className="doc-count">{docs.length} files</span></div>{docs.map(d=><div className="review-doc" key={d.name}><span className="file-icon"><FileCheck2 size={16}/></span><span><strong>{d.name}</strong><small>{d.kind} <i>·</i> {d.size}</small></span><button className="text-button" onClick={()=>openDocument(d)}>View <ArrowRight size={14}/></button></div>)}</section></div><aside className="review-sidebar"><section className="card rubric-card"><div className="card-label">COMMITTEE RUBRIC</div><h2>Review with care</h2><p>Rate each area from 1 (developing) to 5 (exceptional).</p>{[['purpose','Clarity of purpose','The student’s goals and motivation'],['impact','Potential impact','How meaningful the award would be'],['readiness','Academic readiness','Preparation and persistence']].map(([key,label,desc])=><div className="rubric-item" key={key}><div><strong>{label}</strong><small>{desc}</small></div><label className="sr-only" htmlFor={`score-${key}`}>{label} score from 1 to 5</label><select id={`score-${key}`} value={rubric[key]} onChange={e=>setRubric(r=>({...r,[key]:Number(e.target.value)}))}>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n}</option>)}</select></div>)}<div className="rubric-average"><span>Rubric total</span><strong>{average} <small>/ 15</small></strong></div><label className="review-comment-label" htmlFor="review-comment">Private committee note</label><textarea id="review-comment" rows="3" value={comment} onChange={e=>setComment(e.target.value)} placeholder="Add a note for the committee…"/><small className="comment-help">Only committee members can see this note.</small><label className="review-comment-label" htmlFor="student-clarification">Message to student when requesting information</label><textarea id="student-clarification" rows="3" value={clarificationRequest} onChange={e=>setClarificationRequest(e.target.value)} placeholder="Write only the specific question the student should see…"/><div className="rubric-actions">{item.status==='under_review'?<><button className="btn btn-outline full" disabled={!clarificationRequest.trim()} onClick={()=>decide('needs_information',reviewPayload)}><CircleHelp size={15}/> Request information</button><button className="btn btn-primary full" onClick={()=>decide('shortlisted',reviewPayload)}><Check size={16}/> Add to shortlist</button><button className="text-button decline-button" onClick={()=>decide('declined',reviewPayload)}><XCircle size={15}/> Recommend not selected</button></>:<small className="comment-help">{item.status==='needs_information'?'Waiting for the student to reply before review can continue.':'This application is not currently open for a new decision.'}</small>}</div></section><div className="audit-note"><ShieldCheck size={15}/><span>{liveMode?'Reviewer decisions and timestamps are recorded in the committee audit history.':'Demo mode: decisions stay in this browser only.'}</span></div></aside></div></>}
function AdminOverview({applications,nav,scholarships=[],liveMode=false}){const counts={total:applications.length,review:applications.filter(a=>['submitted','under_review'].includes(a.status)).length,approved:applications.filter(a=>a.status==='approved').length};return <><div className="welcome-row"><div><div className="eyebrow">PORTAL ADMINISTRATION</div><h1>Your program, at a glance.</h1><p className="subheading">Keep scholarships and committee workflows running smoothly.</p></div><button className="btn btn-primary" onClick={()=>nav('adminScholarships')}><Plus size={16}/> Manage scholarships</button></div><div className="stats-grid"><Stat label="Applications" value={counts.total} meta="Across active scholarships" icon={<FileText size={17}/>} tone="violet"/><Stat label="In review" value={counts.review} meta="Pending committee decision" icon={<Clock3 size={17}/>} tone="amber"/><Stat label="Approved" value={counts.approved} meta="This cycle" icon={<CheckCircle2 size={17}/>} tone="green"/></div><section className="card admin-table-card"><div className="card-header"><div><div className="card-label">ACTIVE SCHOLARSHIPS</div><h2>Program overview</h2></div><button className="btn btn-outline" onClick={()=>nav('adminScholarships')}>Manage programs <ArrowRight size={15}/></button></div><AdminRows applications={applications} scholarships={scholarships} liveMode={liveMode}/></section></>}
function AdminScholarships({applications,showToast,scholarships=[],reviewers=[],assignments=[],onCreate,onAssign,liveMode}){
 const [open,setOpen]=useState(false);const [title,setTitle]=useState('');const [award,setAward]=useState('25000');const [deadline,setDeadline]=useState('2026-10-20');const [description,setDescription]=useState('');const [incomeLimit,setIncomeLimit]=useState('500000');const [minPercent,setMinPercent]=useState('70');
 const submit=e=>{e.preventDefault();onCreate({title,award_amount:award,deadline,description,income_limit:incomeLimit,min_percent:minPercent,required_documents:['class_xii_marksheet','family_income_certificate']});setOpen(false);setTitle('');setDescription('');};
 return <><SectionTitle eyebrow="PORTAL ADMINISTRATION" title="Scholarship management"><button className="btn btn-primary" onClick={()=>setOpen(true)}><Plus size={16}/> Create scholarship</button></SectionTitle><p className="subheading page-sub">Manage active opportunities and keep committee assignments on track.</p><section className="card admin-table-card"><div className="card-header"><div><div className="card-label">ACTIVE SCHOLARSHIPS</div><h2>Program overview</h2></div><button className="icon-button" aria-label="More program actions" onClick={()=>showToast(liveMode?'Scholarship records are managed here.':'Sample changes stay in this browser.')}><MoreHorizontal size={18}/></button></div><AdminRows applications={applications} scholarships={scholarships} liveMode={liveMode}/></section>
 <section className="card admin-table-card assignment-card"><div className="card-header"><div><div className="card-label">REVIEW WORKFLOW</div><h2>Reviewer assignments</h2></div></div>{liveMode?<>{applications.filter(a=>['submitted','under_review','needs_information','shortlisted'].includes(a.status)).map(app=>{const assigned=assignments.filter(row=>row.application_id===app.id);return <div className="assignment-row" key={app.id}><span><strong>{app.name}</strong><small>{app.scholarship} · {app.status.replaceAll('_',' ')}</small><small>{assigned.length?assigned.map(row=>reviewers.find(r=>r.id===row.reviewer_id)?.full_name||'Reviewer').join(', '):'No reviewer assigned'}</small></span><select aria-label={`Assign reviewer for ${app.name}`} defaultValue=""><option value="" disabled>Choose reviewer</option>{reviewers.map(person=><option key={person.id} value={person.id}>{person.full_name||'Committee reviewer'}</option>)}</select><button className="btn btn-outline" disabled={!reviewers.length} onClick={e=>{const id=e.currentTarget.parentElement.querySelector('select').value;if(id)onAssign(app.id,id);else showToast('Choose a reviewer first.');}}>Assign</button></div>})}{!applications.length&&<p className="empty-note">No applications are available for assignment.</p>}{!reviewers.length&&<p className="empty-note">No reviewer accounts exist yet. An administrator must promote committee accounts in Supabase.</p>}</>:<div className="admin-info"><ShieldCheck size={17}/><span>Reviewer assignment is available after connecting Supabase and signing in with an administrator account.</span></div>}</section><div className="admin-info"><ShieldCheck size={17}/><span><strong>Committee access is role-restricted.</strong> Reviewers can only open applications assigned to their account.</span></div>
 {open&&<div className="modal-backdrop" onClick={()=>setOpen(false)}><section className="modal scholarship-modal" role="dialog" aria-modal="true" aria-labelledby="create-scholarship-title" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setOpen(false)} aria-label="Close"><X size={18}/></button><span className="brand-mark"><BookOpen size={19}/></span><h2 id="create-scholarship-title">Create a scholarship</h2><p>{liveMode?'This record will be saved to the connected portal.':'This sample record will stay in this browser.'}</p><form onSubmit={submit}><label htmlFor="scholarship-title">Scholarship name</label><input id="scholarship-title" required maxLength="120" value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Campus Merit Award"/><label htmlFor="scholarship-award">Award amount per year (₹)</label><input id="scholarship-award" required type="number" min="1" value={award} onChange={e=>setAward(e.target.value)}/><label htmlFor="scholarship-deadline">Application deadline</label><input id="scholarship-deadline" required type="date" value={deadline} onChange={e=>setDeadline(e.target.value)}/><label htmlFor="scholarship-income">Maximum annual family income (₹)</label><input id="scholarship-income" type="number" min="0" required value={incomeLimit} onChange={e=>setIncomeLimit(e.target.value)}/><label htmlFor="scholarship-percent">Minimum marks in previous exam (%)</label><input id="scholarship-percent" type="number" min="0" max="100" required value={minPercent} onChange={e=>setMinPercent(e.target.value)}/><label htmlFor="scholarship-description">Description and eligibility summary</label><textarea id="scholarship-description" rows="3" required maxLength="800" value={description} onChange={e=>setDescription(e.target.value)} placeholder="Who can apply and which documents are required?"/><button className="btn btn-primary full">Create scholarship <ArrowRight size={15}/></button></form></section></div>}</>;
}
function AdminRows({applications,scholarships=[],liveMode=false}){
 const demoPrograms=[{id:'demo-aarohan',title:'Aarohan Udaan Scholarship',award_amount:25000,deadline:'2026-10-20',is_active:true}, ...scholarships, {id:'demo-pmusp',title:'PM-USP CSSS',award_amount:12000,deadline:'2026-10-31',is_active:true,official:true}];
 const records=(liveMode?scholarships:demoPrograms).map(item=>({item,title:item.title,award:item.award_amount,deadline:item.deadline,count:applications.filter(app=>app.scholarshipId?app.scholarshipId===item.id:app.scholarship===item.title).length}));
 return <div className="admin-program-list"><div className="admin-head"><span>SCHOLARSHIP</span><span>AWARD</span><span>DEADLINE</span><span>APPLICATIONS</span><span>STATUS</span></div>{records.map(({item,title,award,deadline,count})=><div className="admin-program-row" key={item.id||title}><span><span className={`tile-icon ${item.official?'green':'saffron'} mini`}><GraduationCap size={16}/></span><strong>{title}</strong></span><span>{Number(award).toLocaleString('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0})} / yr</span><span>{new Date(deadline).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}</span><span>{count}</span><span>{item.official?<span className="status status-blue"><i/>Official listing</span>:<span className={`status ${item.is_active&&new Date(item.deadline).getTime()>=Date.now()?'status-green':'status-muted'}`}><i/>{item.is_active&&new Date(item.deadline).getTime()>=Date.now()?'Open':'Closed'}</span>}</span></div>)}{records.length===0&&<div className="empty-note">No scholarships have been created yet.</div>}</div>;
}
export default App;
